type Mode = 'fixed' | 'sliding'

interface FixedState {
  count: number
  windowIndex: number
}

export class RateLimiter {
  private max: number
  private windowMs: number
  private mode: Mode
  private fixedState = new Map<string, FixedState>()
  private slidingState = new Map<string, number[]>()

  constructor(options: { max: number; windowMs: number; mode: Mode }) {
    this.max = options.max
    this.windowMs = options.windowMs
    this.mode = options.mode
  }

  allow(key: string): boolean {
    return this.mode === 'fixed' ? this.allowFixed(key) : this.allowSliding(key)
  }

  private allowFixed(key: string): boolean {
    const now = Date.now()
    const windowIndex = Math.floor(now / this.windowMs)
    const entry = this.fixedState.get(key)
    if (!entry || entry.windowIndex !== windowIndex) {
      this.fixedState.set(key, { count: 1, windowIndex })
      return true
    }
    if (entry.count >= this.max) return false
    entry.count++
    return true
  }

  private allowSliding(key: string): boolean {
    const now = Date.now()
    const cutoff = now - this.windowMs
    const timestamps = this.slidingState.get(key) ?? []
    while (timestamps.length > 0 && timestamps[0] <= cutoff) {
      timestamps.shift()
    }
    if (timestamps.length >= this.max) {
      this.slidingState.set(key, timestamps)
      return false
    }
    timestamps.push(now)
    this.slidingState.set(key, timestamps)
    return true
  }
}

interface KeyState {
  count: number
  windowIndex: number
}

export class RateLimiter {
  private max: number
  private windowMs: number
  private mode: 'fixed' | 'sliding'
  private state = new Map<string, KeyState>()
  private timestamps = new Map<string, number[]>()

  constructor(options: { max: number; windowMs: number; mode: 'fixed' | 'sliding' }) {
    this.max = options.max
    this.windowMs = options.windowMs
    this.mode = options.mode
  }

  allow(key: string): boolean {
    const now = Date.now()
    if (this.mode === 'sliding') {
      const cutoff = now - this.windowMs
      const ts = this.timestamps.get(key) ?? []
      const fresh = ts.filter((t) => t > cutoff)
      if (fresh.length >= this.max) {
        this.timestamps.set(key, fresh)
        return false
      }
      fresh.push(now)
      this.timestamps.set(key, fresh)
      return true
    }
    const windowIndex = Math.floor(now / this.windowMs)
    const entry = this.state.get(key)
    if (!entry || entry.windowIndex !== windowIndex) {
      this.state.set(key, { count: 1, windowIndex })
      return true
    }
    if (entry.count >= this.max) return false
    entry.count++
    return true
  }
}

